import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        T = int(next(iterator))
    except StopIteration:
        return

    for _ in range(T):
        try:
            M = int(next(iterator))
            N = int(next(iterator))
            s = next(iterator)
        except StopIteration:
            break

        n = len(s)

        # Count substrings with exactly M 'R's
        count_R = 0
        if M == 0:
            count_R = n * (n + 1) // 2
        else:
            r_indices = [-1]
            for i, char in enumerate(s):
                if char == 'R':
                    r_indices.append(i)
            r_indices.append(n)

            total_r = len(r_indices) - 2

            if total_r < M:
                count_R = 0
            else:
                for i in range(len(r_indices) - M):
                    left_idx = r_indices[i]
                    right_idx = r_indices[i + M]

                    left_bound = r_indices[i - 1] if i > 0 else -1
                    right_bound = r_indices[i + M + 1] if i + M + 1 < len(r_indices) else n

                    start_options = left_idx - left_bound
                    end_options = right_bound - right_idx

                    count_R += start_options * end_options

        # Count substrings with exactly N 'K's
        count_K = 0
        if N == 0:
            count_K = n * (n + 1) // 2
        else:k_indices = [-1]
            for i, char in enumerate(s):if char == 'K':k_indices.append(i)
            k_indices.append(n)

            total_k = len(k_indices) - 2

            if total_k < N:
                count_K = 0
            else:
                for i in range(len(k_indices) - N):
                    left_idx = k_indices[i]
                    right_idx = k_indices[i + N]

                    left_bound = k_indices[i - 1] if i > 0 else -1
                     right_bound = k_indices[i + N + 1] if i + N + 1 < len(k_indices) else n

                    start_options = left_idx - left_bound
                     end_options = right_bound - right_idx

                     count_K += start_options * end_options

        print(f"{count_R} {count_K}")

if __name__ == "__main__":
    solve()
